import Foundation

class NewsAPIService {
    private let apiKey: String
    private let baseURL = "https://newsapi.org/v2"

    init(apiKey: String) {
        self.apiKey = apiKey
    }

    func fetchTopHeadlines(category: Category, language: String = "jp") async throws -> [Article] {
        let urlString = "\(baseURL)/top-headlines?country=jp&category=\(category.newsAPICategory)&apiKey=\(apiKey)"

        guard let url = URL(string: urlString) else {
            throw NewsAPIError.invalidURL
        }

        let (data, response) = try await URLSession.shared.data(from: url)

        guard let httpResponse = response as? HTTPURLResponse,
              httpResponse.statusCode == 200 else {
            throw NewsAPIError.invalidResponse
        }

        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let newsResponse = try decoder.decode(NewsAPIResponse.self, from: data)

        return newsResponse.articles.compactMap { apiArticle in
            guard let title = apiArticle.title,
                  let url = apiArticle.url else {
                return nil
            }

            return Article(
                title: title,
                summary: apiArticle.description ?? "詳細は記事をご覧ください",
                imageURL: apiArticle.urlToImage,
                articleURL: url,
                sourceName: apiArticle.source.name,
                publishedDate: apiArticle.publishedAt ?? Date(),
                category: category
            )
        }
    }
}

// MARK: - NewsAPI Response Models

struct NewsAPIResponse: Codable {
    let status: String
    let totalResults: Int
    let articles: [NewsAPIArticle]
}

struct NewsAPIArticle: Codable {
